<?php require_once __DIR__.'/../_init.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM rekening WHERE id=?')->execute([(int)$_GET['delete']]);redirect('index.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('INSERT INTO rekening(bank,nomor_rekening,atas_nama,urutan) VALUES(?,?,?,?)')->execute([trim($_POST['bank']),trim($_POST['nomor_rekening']),trim($_POST['atas_nama']),(int)$_POST['urutan']]);redirect('index.php');}$rows=$pdo->query('SELECT * FROM rekening ORDER BY urutan,id')->fetchAll();admin_header('Rekening');?><div class="admin-card"><h1>Rekening</h1><form method="post" class="form"><?=csrf_field()?><div class="grid2"><input name="bank" placeholder="BCA" required><input name="nomor_rekening" placeholder="123456789" required><input name="atas_nama" placeholder="Nama Pemilik" required><input type="number" name="urutan" value="1"></div><button class="btn">Tambah</button></form></div><div class="admin-card"><table class="table"><tr><th>Bank</th><th>Nomor</th><th>Atas Nama</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['bank'])?></td><td><?=e($r['nomor_rekening'])?></td><td><?=e($r['atas_nama'])?></td><td><a href="?delete=<?=$r['id']?>" onclick="return confirm('Hapus?')">Hapus</a></td></tr><?php endforeach;?></table></div><?php admin_footer();?>
